import fs from 'node:fs';
import {execFileSync} from 'node:child_process';
import toml from 'toml';
const file = 'docs/dotfiles.md';
const current = fs.readFileSync(file, 'utf8');
const previous = execFileSync('git', ['show', 'HEAD:' + file], {encoding: 'utf8'});
const html = fs.readFileSync('docs/.vitepress/dist/dotfiles.html', 'utf8');
const anchors = [...previous.matchAll(/^#{1,6} (.+)$/gm)].map(([,title]) => title.toLowerCase().replaceAll(' ', '-'));
for (const anchor of anchors) {
  if (!html.includes(`id="${anchor}"`)) throw new Error(`Missing old anchor: ${anchor}`);
}
let snippets = 0;
for (const [,example] of current.matchAll(/```toml\n([\s\S]*?)```/g)) {
  toml.parse(example);
  snippets++;
}
for (const [,url] of current.matchAll(/\]\((\/[^)]+|#[^)]+)\)/g)) {
  const [page,anchor] = url.split('#');
  const target = page ? 'docs/.vitepress/dist' + page : 'docs/.vitepress/dist/dotfiles.html';
  const output = fs.readFileSync(target, 'utf8');
  if (anchor && !output.includes(`id="${anchor}"`)) throw new Error(`Missing linked anchor: ${url}`);
}
console.log(`Parsed ${snippets} TOML examples; preserved all ${anchors.length} original heading anchors; verified local documentation links.`);
